window.TADABBUR_NAZIAT = {"_meta":{"description":"تدبّر سورة النازعات (٧٩)، وسورةٌ مكّيّةٌ. محورُها القسمُ بالملائكةِ (النازعاتِ الناشطاتِ السابحاتِ السابقاتِ المدبّرات) على وقوعِ البعث، ووصفُ الراجفةِ والرادفةِ وأهوالِ القيامة، والردُّ على منكري البعث، ثم قصّةُ موسى مع فرعونَ الطاغي وأخذِ الله له نكالًا، والاستدلالُ على البعثِ بخلقِ السماءِ والأرضِ ودحوها وإخراجِ الماءِ والمرعى، ثم الطامّةِ الكبرى وانقسامِ الناسِ بين من طغى وآثر الدنيا فمأواه الجحيم، ومن خاف مقامَ ربّه ونهى النفسَ عن الهوى فمأواه الجنّة، وختامِها بأنّ علمَ الساعةِ عند الله والنبيُّ منذِر. فيها «فأما من طغى وآثر الحياة الدنيا فإن الجحيم هي المأوى»، و«وأما من خاف مقام ربه ونهى النفس عن الهوى فإن الجنة هي المأوى».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":79,"name":"النازعات","total_ayahs":46,"audio":["audio/079001.mp3","audio/079002.mp3","audio/079003.mp3","audio/079004.mp3","audio/079005.mp3","audio/079006.mp3","audio/079007.mp3","audio/079008.mp3","audio/079009.mp3","audio/079010.mp3"],"passages":[{"title":"القسمُ بالملائكةِ وأهوالُ القيامةِ والردُّ على منكري البعث","range":[1,14],"theme":"القسمُ بالملائكة «والنازعات غرقا... فالمدبرات أمرا»، وأهوالِ القيامة «يوم ترجف الراجفة تتبعها الرادفة قلوب يومئذ واجفة أبصارها خاشعة»، واستبعادِ المكذّبين «أإنا لمردودون في الحافرة أإذا كنا عظاما نخرة»، والردِّ عليهم «فإنما هي زجرة واحدة فإذا هم بالساهرة»","verses":[{"n":1,"reflection":{"text":"«والنازعات غرقا»: أُقسِم بالملائكةِ التي تنزع أرواحَ الكفّارِ نزعًا شديدًا مُغرِقًا في النزع؛ ففي هذا قسمٌ بالملائكةِ على وقوعِ البعث، وتذكيرٌ بشدّةِ نزعِ أرواحِ الكفّار؛ فاستعدّ لنزعِ روحك بالإيمانِ لتسهل، فنزعُ روحِ الكافرِ شديد، فاعمل لتسهيلِ خروجها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ لخروجِ الروحِ بالإيمانِ والعمل."},"action":{"text":"تأمّل القسمَ بالنازعات: والنازعاتِ غرقًا، أي أُقسِم بالملائكةِ التي تنزع أرواحَ الكفّارِ والفجّارِ من أجسادهم نزعًا شديدًا عنيفًا، تُغرِق في النزعِ حتى تبلغ أقصى الجسدِ ثم تنزعها بشدّة، كما يُغرَق النازعُ في القوس؛ وقيل: النجومُ تنزع من أفقٍ إلى أفق «والنازعات غرقا»؛ ففي هذا بيانُ القسمِ بالملائكةِ النازعاتِ لأرواحِ الكفّارِ بشدّة، على وقوعِ البعثِ والجزاء، وفيه تذكيرٌ بشدّةِ نزعِ روحِ الكافر؛ فنزعُ روحِ الكافرِ شديدٌ عنيف، بخلافِ روحِ المؤمنِ التي تخرج بسهولةٍ ويسر؛ فاستعدّ أنت لخروجِ روحك بالإيمانِ والعملِ الصالحِ والتوبة، ليُهوَّن عليك النزع؛ ولو ترى إذ الظالمون في غمراتِ الموتِ والملائكةُ باسطو أيديهم أخرجوا أنفسكم؛ الذين تتوفّاهم الملائكةُ طيّبين؛ فنزعُ روحِ الكافرِ شديد، وخروجُ روحِ المؤمنِ يسير؛ فاعمل لتسهيلِ خروجِ روحك، وآمن، واستعدّ؛ فمن آمن وعمل هُوِّن عليه النزع، ومن كفر شُدِّد عليه؛ فاجعل الاستعدادَ لخروجِ الروحِ بالإيمانِ والعملِ دأبك."}},{"n":2,"reflection":{"text":"«والناشطات نشطا»، والملائكةِ التي تنشط أرواحَ المؤمنين (تخرجها) برفقٍ ونشاطٍ ويسر؛ ففي هذا قسمٌ بالملائكةِ وتذكيرٌ بيسرِ خروجِ روحِ المؤمن؛ فاعمل لتكون روحك ممّا تنشطه الملائكةُ برفق، فروحُ المؤمنِ تخرج بيسر، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لييسّر خروجَ الروحِ برفقِ الملائكة."},"action":{"text":"تأمّل القسمَ بالناشطات: والناشطاتِ نشطًا، أي الملائكةِ التي تنشط أرواحَ المؤمنين، أي تحلّها وتخرجها من أجسادهم برفقٍ ونشاطٍ ويسرٍ وسهولة، كما يُنشَط العِقالُ من يدِ البعيرِ فيُحَلّ برفق؛ فتخرج روحُ المؤمنِ سلسةً هيّنة «والناشطات نشطا»؛ ففي هذا بيانُ القسمِ بالملائكةِ الناشطاتِ لأرواحِ المؤمنين برفقٍ ويسر، على وقوعِ البعث، وفيه تذكيرٌ بيسرِ خروجِ روحِ المؤمن؛ فروحُ المؤمنِ تخرج بيسرٍ ورفقٍ وبشرى، بخلافِ روحِ الكافر؛ فاعمل أنت بالإيمانِ والطاعةِ لتكون روحك ممّا تنشطه الملائكةُ برفقٍ وبشرى؛ الذين تتوفّاهم الملائكةُ طيّبين يقولون سلامٌ عليكم؛ يا أيتها النفسُ المطمئنّة ارجعي إلى ربّك راضية؛ فروحُ المؤمنِ تخرج بيسرٍ ورفق، والعملُ الصالحُ سببُ ذلك؛ فاعمل لها، وآمن، واستعدّ؛ فمن آمن وعمل نُشِطت روحه برفق، ومن كفر نُزِعت بشدّة؛ فاجعل العملَ لييسّر خروجَ الروحِ دأبك."}},{"n":3,"reflection":{"text":"«والسابحات سبحا»، والملائكةِ التي تسبح في نزولها وصعودها (أو في قبضِ الأرواح) سبحًا سريعًا؛ ففي هذا قسمٌ بالملائكةِ السابحاتِ المنقاداتِ لأمرِ الله؛ فاقتدِ بالملائكةِ في سرعةِ الانقيادِ لأمرِ الله، فالملائكةُ سراعٌ في طاعته، فأطعه مسرعًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالملائكةِ في سرعةِ الانقيادِ لأمرِ الله."},"action":{"text":"تأمّل القسمَ بالسابحات: والسابحاتِ سبحًا، أي الملائكةِ التي تسبح في نزولها من السماءِ وصعودها إليها بأمرِ الله، أو تسبح بأرواحِ المؤمنين إلى السماء، سبحًا سريعًا منقادًا؛ وقيل: النجومُ تسبح في أفلاكها «والسابحات سبحا»؛ ففي هذا بيانُ القسمِ بالملائكةِ السابحاتِ المسرعاتِ في تنفيذِ أمرِ الله، على وقوعِ البعث، وفيه بيانُ سرعةِ انقيادِ الملائكةِ لأمرِ الله وطاعتها؛ فالملائكةُ سراعٌ في طاعةِ الله لا يعصونه؛ فاقتدِ أنت بالملائكةِ في سرعةِ الانقيادِ لأمرِ الله والمبادرةِ إلى طاعته، ولا تتباطأ ولا تتثاقل؛ لا يعصون الله ما أمرهم ويفعلون ما يؤمرون؛ يسبّحون الليلَ والنهارَ لا يفترون؛ بل عبادٌ مكرمون لا يسبقونه بالقولِ وهم بأمره يعملون؛ فالملائكةُ سراعٌ في الطاعة، والاقتداءُ بها في المبادرةِ إلى الخير؛ فأطع الله مسرعًا، وبادر إلى طاعته؛ فمن بادر إلى الطاعةِ اقتدى بالملائكة، ومن تثاقل خالفها؛ فاجعل الاقتداءَ بالملائكةِ في سرعةِ الانقيادِ دأبك."}},{"n":4,"reflection":{"text":"«فالسابقات سبقا»: فالملائكةِ التي تسبق بأرواحِ المؤمنين إلى الجنّة، أو تسبق في تنفيذِ أمرِ الله؛ ففي هذا قسمٌ بالملائكةِ السابقاتِ إلى الخير؛ فسابق إلى الخيراتِ كسبقِ الملائكة، فالمسابقةُ إلى الخيرِ من صفاتِ المقرّبين، فسابق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المسابقةُ إلى الخيراتِ اقتداءً بالملائكة."},"action":{"text":"تأمّل القسمَ بالسابقات: فالسابقاتِ سبقًا، أي الملائكةِ التي تسبق بأرواحِ المؤمنين إلى الجنّةِ ومنازلِ الكرامة، أو تسبق غيرها إلى تنفيذِ أمرِ الله، أو سبقت بالإيمانِ والطاعة؛ فهي سابقةٌ إلى الخير «فالسابقات سبقا»؛ ففي هذا بيانُ القسمِ بالملائكةِ السابقاتِ إلى الخيرِ وتنفيذِ أمرِ الله، على وقوعِ البعث، وفيه بيانُ فضلِ المسابقةِ إلى الخيرات؛ فالمسابقةُ إلى الخيرِ من صفاتِ الملائكةِ والمقرّبين؛ فسابق أنت إلى الخيراتِ والطاعاتِ كسبقِ الملائكة، ولا تتأخّر عن الخير؛ والسابقون السابقون أولئك المقرّبون؛ فاستبقوا الخيرات؛ وسارعوا إلى مغفرةٍ من ربّكم؛ سابقوا إلى مغفرةٍ من ربّكم وجنّة؛ فالمسابقةُ إلى الخيرِ سبيلُ القربِ والفوز؛ فسابق، وبادر، ولا تتأخّر؛ فمن سابق إلى الخيرِ قرُب وفاز، ومن تأخّر خسر؛ فاجعل المسابقةَ إلى الخيراتِ دأبك."}},{"n":5,"reflection":{"text":"«فالمدبرات أمرا»: فالملائكةِ التي تدبّر ما وكّلها الله به من الأمرِ (بإذنه) في السماواتِ والأرض؛ ففي هذا قسمٌ بالملائكةِ المدبّراتِ بأمرِ الله؛ فاعلم أنّ التدبيرَ لله والملائكةُ منفّذةٌ بإذنه، فوّض أمرك إلى مدبّرِ الأمور، فالله المدبّرُ وحده، فتوكّل عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بأنّ التدبيرَ لله والتوكّلُ عليه."},"action":{"text":"تأمّل القسمَ بالمدبّرات: فالمدبّراتِ أمرًا، أي الملائكةِ التي تدبّر ما وكّلها الله به من الأمورِ بإذنه وأمره: من تدبيرِ الأمطارِ والرياحِ والأرزاقِ والآجالِ وقبضِ الأرواحِ وحفظِ العباد؛ فهي منفّذةٌ لأمرِ الله لا تستقلّ بشيء «فالمدبرات أمرا»؛ ففي هذا بيانُ القسمِ بالملائكةِ المدبّراتِ للأمورِ بإذنِ الله وأمره، على وقوعِ البعث، وفيه بيانُ أنّ التدبيرَ الحقيقيَّ لله وحده، والملائكةُ منفّذةٌ بأمره؛ فالتدبيرُ لله، والملائكةُ منفّذةٌ لأمره؛ فأقرّ أنت بأنّ مدبّرَ الأمورِ كلِّها هو الله، والملائكةُ خدمٌ منفّذون بإذنه، ففوّض أمرك إلى الله المدبّرِ الحكيم، وتوكّل عليه؛ يدبّر الأمرَ من السماءِ إلى الأرض؛ يدبّر الأمرَ يفصّل الآيات؛ فمن يدبّر الأمر فسيقولون الله؛ فالتدبيرُ لله وحده، والملائكةُ منفّذةٌ بأمره؛ ففوّض أمرك إليه، وتوكّل عليه، وأقرّ بتدبيره؛ فمن فوّض أمره لله وتوكّل كُفِي، ومن اعتمد على غيره خُذِل؛ فاجعل الإقرارَ بأنّ التدبيرَ لله والتوكّلَ عليه دأبك."}},{"n":6,"reflection":{"text":"«يوم ترجف الراجفة»: يومَ تضطرب الأرضُ اضطرابًا شديدًا بالنفخةِ الأولى؛ ففي هذا بيانُ بدءِ أهوالِ القيامةِ بالرجفة؛ فاستعدّ ليومٍ ترجف فيه الأرض، فأهوالُ القيامةِ تبدأ بالرجفة، فاعمل قبلها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ الرجفةِ والأهوال."},"action":{"text":"تأمّل بدءَ الأهوال: يومَ ترجف الراجفةُ، أي يومَ تضطرب الأرضُ وترتجّ وتتزلزل زلزلةً شديدةً عند النفخةِ الأولى في الصور، فتموت الخلائق؛ والراجفةُ: النفخةُ الأولى التي يموت بها من في السماواتِ والأرض «يوم ترجف الراجفة»؛ ففي هذا بيانُ بدءِ أهوالِ القيامةِ بالرجفة (النفخةِ الأولى) التي تضطرب بها الأرضُ ويموت الخلائق؛ فأهوالُ القيامةِ تبدأ بالرجفةِ العظيمة؛ فاستعدّ أنت ليومٍ ترجف فيه الأرضُ وتضطرب، بالإيمانِ والعملِ الصالحِ قبل فواتِ الأوان؛ يومَ ترجف الأرضُ والجبال؛ إذا رُجّت الأرضُ رجًّا؛ إذا زُلزِلت الأرضُ زلزالها؛ فأهوالُ القيامةِ تبدأ بالرجفة، فالاستعدادُ لها واجب؛ فاستعدّ، واعمل، ولا تسوّف؛ فمن استعدّ لها أمِن، ومن غفل فوجئ؛ فاجعل الاستعدادَ ليومِ الرجفةِ دأبك."}},{"n":7,"reflection":{"text":"«تتبعها الرادفة»: تتبع الرجفةَ الأولى النفخةُ الثانيةُ الرادفة (نفخةُ البعث)؛ ففي هذا بيانُ تتابعِ نفختي الفزعِ والبعث؛ فاستعدّ ليومٍ تتبع فيه الرادفةُ الراجفةَ للبعث، فالبعثُ يعقب الفزع، فاعمل لِما بعدهما.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للبعثِ الذي تعقبه الرادفة."},"action":{"text":"تأمّل تتابعَ النفختين: تتبعها، أي تتبع الراجفةَ (النفخةَ الأولى)، والرادفةُ، أي النفخةُ الثانيةُ التي تردفها وتتبعها، وهي نفخةُ البعثِ التي يقوم بها الناسُ من قبورهم للحساب؛ فبينهما مدّةٌ ثم يقع البعث «تتبعها الرادفة»؛ ففي هذا بيانُ تتابعِ نفختي القيامة: الراجفةِ (نفخةِ الموتِ والفزع) والرادفةِ (نفخةِ البعث)، فيموت الخلقُ ثم يُبعَثون؛ فالبعثُ يعقب الفزعَ والموت؛ فاستعدّ أنت ليومٍ تتبع فيه الرادفةُ الراجفةَ فتُبعَث للحساب، بالإيمانِ والعملِ الصالح، واعمل لِما بعد النفختين؛ فإذا نُفِخ في الصورِ نفخةٌ واحدة... فيومئذٍ وقعت الواقعة؛ ثم نُفِخ فيه أخرى فإذا هم قيامٌ ينظرون؛ ونُفِخ في الصورِ فصعق من في السماواتِ ومن في الأرضِ إلا من شاء الله ثم نُفِخ فيه أخرى؛ فالبعثُ يعقب الفزع، فالاستعدادُ له واجب؛ فاستعدّ، واعمل، وأيقن بالبعث؛ فمن استعدّ للبعثِ أمِن، ومن غفل فوجئ؛ فاجعل الاستعدادَ للبعثِ دأبك."}},{"n":8,"reflection":{"text":"«قلوب يومئذ واجفة»: قلوبٌ يومئذٍ خائفةٌ مضطربةٌ قلقةٌ من الهول (قلوبُ الكفّار)؛ ففي هذا بيانُ شدّةِ خوفِ قلوبِ المكذّبين يومَ القيامة؛ فاعمل لتطمئنّ قلبك يومَ تجف القلوب، فالأمنُ يومئذٍ ثمرةُ الإيمانِ والعمل، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لطمأنينةِ القلبِ يومَ تجف القلوب."},"action":{"text":"تأمّل خوفَ القلوب: قلوبٌ يومئذٍ، أي يومَ القيامةِ، واجفةٌ، أي خائفةٌ مضطربةٌ قلقةٌ شديدةُ الاضطرابِ والفزعِ من هولِ ما ترى؛ وهي قلوبُ الكفّارِ والمكذّبين الذين لم يستعدّوا «قلوب يومئذ واجفة»؛ ففي هذا بيانُ شدّةِ خوفِ قلوبِ المكذّبين واضطرابها يومَ القيامةِ من الأهوال، بخلافِ قلوبِ المؤمنين المطمئنّة؛ فقلوبُ المكذّبين يومئذٍ خائفةٌ مضطربة؛ فاعمل أنت لتطمئنّ قلبك يومَ تجف القلوبُ وتضطرب، بالإيمانِ والعملِ الصالح، فإنّ الأمنَ والطمأنينةَ يومئذٍ ثمرةُ الإيمانِ والعمل؛ لا يحزنهم الفزعُ الأكبرُ وتتلقّاهم الملائكة؛ الذين آمنوا وتطمئنّ قلوبهم بذكرِ الله؛ وهم من فزعٍ يومئذٍ آمنون؛ فقلوبُ المكذّبين واجفة، وقلوبُ المؤمنين آمنة؛ فاعمل لطمأنينةِ قلبك، وآمن، واستعدّ؛ فمن آمن وعمل اطمأن قلبه، ومن كذّب وجف قلبه؛ فاجعل العملَ لطمأنينةِ القلبِ دأبك."}},{"n":9,"reflection":{"text":"«أبصارها خاشعة»: أبصارُ أصحابِ تلك القلوبِ ذليلةٌ خاضعةٌ من الهولِ والخزي؛ ففي هذا بيانُ ذلِّ المكذّبين يومَ القيامةِ ظاهرًا وباطنًا؛ فاعمل لتكون من أهلِ العزّةِ يومَ يذلّ المكذّبون، فذلُّ المكذّبين يظهر في أبصارهم، فاعمل للعزّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للعزّةِ يومَ القيامةِ والحذرُ من ذلِّ المكذّبين."},"action":{"text":"تأمّل ذلَّ الأبصار: أبصارها، أي أبصارُ أصحابِ تلك القلوبِ الواجفة، خاشعةٌ، أي ذليلةٌ خاضعةٌ منكسرةٌ من شدّةِ الهولِ والخزيِ والفزع، لا ترتفع ولا تتحرّك؛ فقد ظهر عليهم الذلُّ في أبصارهم كما وجفت قلوبهم «أبصارها خاشعة»؛ ففي هذا بيانُ ذلِّ المكذّبين يومَ القيامةِ ظاهرًا (خشوعِ الأبصار) وباطنًا (وجيفِ القلوب)، فقد جمعوا ذلَّ الظاهرِ والباطن؛ فذلُّ المكذّبين يومَ القيامةِ يظهر في أبصارهم وقلوبهم؛ فاعمل أنت لتكون من أهلِ العزّةِ والأمنِ يومَ يذلّ المكذّبون، بالإيمانِ والعملِ الصالح؛ خاشعةً أبصارهم ترهقهم ذلّة؛ خاشعين من الذلِّ ينظرون من طرفٍ خفيّ؛ وجوهٌ يومئذٍ خاشعة؛ فذلُّ المكذّبين ظاهرٌ وباطن، وعزّةُ المؤمنين بالإيمانِ والعمل؛ فاعمل للعزّة، وآمن، واستعدّ؛ فمن آمن وعمل عزّ، ومن كذّب ذلّ؛ فاجعل العملَ للعزّةِ والحذرَ من ذلِّ المكذّبين دأبك."}},{"n":10,"reflection":{"text":"«يقولون أإنا لمردودون في الحافرة»: يقول المنكرون للبعث مستبعدين: أنُرَدّ بعد الموتِ إلى الحياةِ الأولى (أو إلى قبورنا أحياء)؟ ففي هذا بيانُ استبعادِ المكذّبين للبعث؛ فأيقن بالبعثِ ولا تستبعده كالمكذّبين، فالبعثُ حقٌّ لا يُستبعَد، فأيقن به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ وعدمُ استبعاده."},"action":{"text":"تأمّل استبعادَهم: يقولون، أي المنكرون للبعثِ استبعادًا وإنكارًا، أإنا لمردودون في الحافرةِ، أي أنُرَدّ بعد الموتِ إلى الحالةِ الأولى (الحياة)، أو إلى أوّلِ أمرنا أحياءً كما كنّا؛ والحافرةُ: أوّلُ الأمرِ والحالةُ الأولى؛ فأنكروا أن يُرَدّوا أحياءً بعد موتهم «يقولون أإنا لمردودون في الحافرة»؛ ففي هذا بيانُ استبعادِ المكذّبين للبعثِ وإنكارهم أن يُرَدّوا إلى الحياةِ بعد الموت؛ فالمكذّبون يستبعدون البعثَ ويُنكِرونه؛ فأيقن أنت بالبعثِ يقينًا جازمًا، ولا تستبعده كالمكذّبين، فالذي خلقك أوّلًا قادرٌ على ردّك؛ وقالوا أإذا كنّا عظامًا ورفاتًا أإنا لمبعوثون خلقًا جديدًا قل كونوا حجارةً أو حديدًا؛ زعم الذين كفروا أن لن يُبعَثوا قل بلى وربّي لتُبعَثنّ؛ فالبعثُ حقٌّ لا يُستبعَد، وإنكارُه جهل؛ فأيقن به، ولا تستبعده، واستعدّ؛ فمن أيقن بالبعثِ استعدّ، ومن استبعده خسر؛ فاجعل اليقينَ بالبعثِ وعدمَ استبعاده دأبك."}},{"n":11,"reflection":{"text":"«أإذا كنا عظاما نخرة»: أنُبعَث إذا كنّا عظامًا باليةً متفتّتةً؟ (استبعادٌ آخرُ للبعث)؛ ففي هذا بيانُ زيادةِ استبعادِ المكذّبين للبعثِ بعد بلاءِ العظام؛ فأيقن بقدرةِ الله على بعثِ العظامِ البالية، فمن خلقها أوّلًا يعيدها، فأيقن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله على بعثِ العظامِ البالية."},"action":{"text":"تأمّل زيادةَ استبعادهم: أإذا كنّا عظامًا نخرةً، أي أنُرَدّ ونُبعَث إذا كنّا عظامًا باليةً متفتّتةً مجوّفةً قد نخرت وبليت وتفرّقت؟ استبعادٌ آخرُ للبعثِ بعد صيرورةِ العظامِ رميمًا «أإذا كنا عظاما نخرة»؛ ففي هذا بيانُ زيادةِ استبعادِ المكذّبين للبعثِ بعد بلاءِ العظامِ وتفتّتها، إذ استبعدوا إعادةَ الحياةِ إلى عظامٍ نخرة؛ فالمكذّبون يستبعدون بعثَ العظامِ البالية؛ فأيقن أنت بقدرةِ الله على بعثِ العظامِ البالية وإعادةِ الحياةِ إليها، فمن أنشأها أوّلَ مرّةٍ قادرٌ على إعادتها؛ قال من يحيي العظامَ وهي رميم قل يحييها الذي أنشأها أوّلَ مرّة؛ أيحسب الإنسانُ ألن نجمع عظامه بلى قادرين؛ فقدرةُ الله على بعثِ العظامِ البالية متحقّقة، وإنكارُها جهل؛ فأيقن بها، ولا تستبعد، واستعدّ؛ فمن أيقن بالبعثِ استعدّ، ومن استبعده خسر؛ فاجعل اليقينَ بقدرةِ الله على البعثِ دأبك."}},{"n":12,"reflection":{"text":"«قالوا تلك إذا كرة خاسرة»: قالوا (استهزاءً): تلك الرجعةُ إذًا رجعةٌ خاسرةٌ (لا تكون، ولو كانت لخسرنا)؛ ففي هذا بيانُ استهزاءِ المكذّبين بالبعثِ ووصفِه بالخسارة؛ فاعلم أنّ الكرةَ (البعثَ) حقٌّ، والخاسرُ من كذّب بها لا من أُعيد، فالبعثُ حقٌّ رابحٌ للمؤمن، فأيقن واعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ البعثَ حقٌّ رابحٌ للمؤمن، والحذرُ من خسارةِ المكذّب."},"action":{"text":"تأمّل استهزاءهم: قالوا، أي المكذّبون استهزاءً وتكذيبًا، تلك إذًا كرّةٌ خاسرةٌ، أي تلك الرجعةُ والإعادةُ إلى الحياةِ إن كانت (وهم لا يصدّقون بها) فهي رجعةٌ ذاتُ خسران، أو قالوا: لئن رُدِدنا لنخسرنّ؛ فاستهزؤوا بالبعثِ ووصفوه بالخسارة «قالوا تلك إذا كرة خاسرة»؛ ففي هذا بيانُ استهزاءِ المكذّبين بالبعثِ وتكذيبهم به، ووصفِهم للكرّةِ بالخسارةِ إمّا إنكارًا أو خوفًا من الخسران؛ والحقُّ أنّ البعثَ حقٌّ، والخاسرُ فيه هو المكذّبُ لا المؤمن؛ فالبعثُ حقٌّ، والخاسرُ من كذّب به؛ فأيقن أنت بأنّ البعثَ (الكرّةَ) حقٌّ واقع، وأنه رابحٌ للمؤمنِ العاملِ خاسرٌ على الكافرِ المكذّب، فاعمل لتربح يومَ البعث؛ قد خسر الذين كذّبوا بلقاءِ الله؛ وأمّا من خفّت موازينه فأولئك الذين خسروا أنفسهم؛ ونادوا يا مالكُ؛ فالبعثُ حقٌّ رابحٌ للمؤمنِ خاسرٌ على المكذّب؛ فأيقن به، واعمل لتربح، واحذر خسارةَ المكذّب؛ فمن آمن وعمل ربح، ومن كذّب خسر؛ فاجعل اليقينَ بأنّ البعثَ حقٌّ رابحٌ والحذرَ من خسارةِ المكذّبِ دأبك."}},{"n":13,"reflection":{"text":"«فإنما هي زجرة واحدة»: فإنما البعثةُ صيحةٌ واحدةٌ (النفخةُ الثانية) لا كلفةَ فيها على الله؛ ففي هذا بيانُ سهولةِ البعثِ على الله بزجرةٍ واحدة؛ فأيقن بأنّ البعثَ يسيرٌ على الله بصيحةٍ واحدة، فالبعثُ سهلٌ على الله، فلا تستبعده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بسهولةِ البعثِ على الله."},"action":{"text":"تأمّل سهولةَ البعث: فإنما هي، أي البعثةُ والكرّةُ التي استبعدوها، زجرةٌ واحدةٌ، أي صيحةٌ واحدةٌ (النفخةُ الثانيةُ في الصور)، لا تكرارَ فيها ولا معالجةَ ولا كلفةَ على الله، فيقوم الخلقُ كلُّهم أحياءً في الحال «فإنما هي زجرة واحدة»؛ ففي هذا بيانُ سهولةِ البعثِ على الله ويسرِه، فهو يقع بزجرةٍ واحدةٍ (صيحةٍ) لا كلفةَ فيها، ردًّا على استبعادِ المكذّبين؛ فالبعثُ سهلٌ يسيرٌ على الله بزجرةٍ واحدة؛ فأيقن أنت بأنّ البعثَ يسيرٌ على الله لا يحتاج إلى كلفةٍ ولا معالجة، بل يقع بصيحةٍ واحدة، فلا تستبعده؛ وما أمرُ الساعةِ إلا كلمحِ البصرِ أو هو أقرب؛ إن كانت إلا صيحةً واحدةً فإذا هم جميعٌ لدينا محضرون؛ ما خلقكم ولا بعثكم إلا كنفسٍ واحدة؛ فالبعثُ يسيرٌ على الله بزجرةٍ واحدة؛ فأيقن به، ولا تستبعده، واستعدّ؛ فمن أيقن بيسرِ البعثِ آمن، ومن استبعده جهل؛ فاجعل اليقينَ بسهولةِ البعثِ على الله دأبك."}},{"n":14,"reflection":{"text":"«فإذا هم بالساهرة»: فإذا الخلقُ أحياءٌ على وجهِ الأرضِ (الساهرة) بعد أن كانوا في بطنها؛ ففي هذا بيانُ سرعةِ قيامِ الخلقِ للبعثِ على وجهِ الأرض؛ فأيقن بأنك ستقوم على وجهِ الأرضِ للحساب، فالبعثُ يجمع الخلقَ على الساهرة، فاستعدّ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ والقيامِ للحساب، والاستعدادُ له."},"action":{"text":"تأمّل قيامَ الخلق: فإذا هم، أي الخلقُ الذين كانوا أمواتًا في بطنِ الأرض، بالساهرةِ، أي على وجهِ الأرضِ ظاهرين أحياءً قيامًا ينظرون، بعد أن كانوا في جوفها أمواتًا؛ والساهرةُ: وجهُ الأرضِ ومستواها؛ ففي لحظةٍ بعد الزجرةِ صاروا أحياءً على ظهرها «فإذا هم بالساهرة»؛ ففي هذا بيانُ سرعةِ قيامِ الخلقِ للبعثِ بعد الزجرةِ الواحدة، فيصيرون أحياءً على وجهِ الأرضِ للحسابِ والجزاء؛ فالبعثُ يجمع الخلقَ أحياءً على وجهِ الأرضِ في لحظة؛ فأيقن أنت بأنك ستُبعَث وتقوم على وجهِ الأرضِ للحساب، فاستعدّ له بالإيمانِ والعملِ الصالح؛ يومَ يخرجون من الأجداثِ سراعًا؛ ونُفِخ في الصورِ فإذا هم من الأجداثِ إلى ربّهم ينسلون؛ يومَ تبدّل الأرضُ غيرَ الأرض؛ فالبعثُ يجمع الخلقَ على الساهرةِ للحساب؛ فأيقن به، واستعدّ، واعمل؛ فمن استعدّ للبعثِ أمِن، ومن غفل فوجئ؛ فاجعل اليقينَ بالبعثِ والاستعدادَ له دأبك."}}]},{"title":"قصّةُ موسى مع فرعونَ الطاغي وأخذِه نكالا","range":[15,26],"theme":"تشويقُ القصّة «هل أتاك حديث موسى»، وتشريفِ موسى بالنداء «بالواد المقدس طوى»، والأمرِ بدعوةِ فرعون برفق «اذهب إلى فرعون إنه طغى فقل هل لك إلى أن تزكى وأهديك إلى ربك فتخشى»، وإقامةِ الحجّة «فأراه الآية الكبرى»، ومقابلةِ فرعون «فكذب وعصى ثم أدبر يسعى فحشر فنادى فقال أنا ربكم الأعلى»، وأخذِه «فأخذه الله نكال الآخرة والأولى إن في ذلك لعبرة لمن يخشى»","verses":[{"n":15,"reflection":{"text":"«هل أتاك حديث موسى»: هل بلغك، يا محمد، خبرُ موسى مع فرعون؟ (تشويقٌ وتقريرٌ للعبرة)؛ ففي هذا تمهيدٌ لقصّةِ موسى وفرعونَ للاعتبارِ والتسلية؛ فتدبّر قصّةَ موسى للاعتبارِ بعاقبةِ الطغيان، فقصصُ الأنبياءِ عبرةٌ وتسلية، فتدبّرها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ قصصِ الأنبياءِ للاعتبارِ والتسلية."},"action":{"text":"تأمّل التشويقَ للقصّة: هل أتاك، يا محمد، حديثُ موسى، أي هل بلغك وجاءك خبرُ موسى عليه السلام مع فرعون؟ استفهامٌ للتشويقِ والتقريرِ وتنبيهِ السامعِ للاعتبار؛ فقصّةُ موسى مع فرعونَ عبرةٌ لمن يخشى، وتسليةٌ للنبيِّ ﷺ فيما يلقاه من قومه «هل أتاك حديث موسى»؛ ففي هذا بيانُ تمهيدِ الله لقصّةِ موسى مع فرعونَ بالاستفهامِ التشويقيّ، للاعتبارِ بعاقبةِ الطغيانِ وتسليةِ النبيّ؛ فقصصُ الأنبياءِ عبرةٌ وتسليةٌ وموعظة؛ فتدبّر أنت قصصَ الأنبياءِ (كقصّةِ موسى وفرعون) للاعتبارِ بعاقبةِ الطغيانِ والتكذيب، والتأسّي بالأنبياءِ في الصبر، وأخذِ الموعظة؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ ونقصّ عليك من أنباءِ الرسلِ ما نثبّت به فؤادك؛ فبذلك فليفرحوا؛ فقصصُ الأنبياءِ عبرةٌ وتسليةٌ وثباتٌ للقلب؛ فتدبّرها، واعتبر بها، وتأسَّ؛ فمن تدبّرها اعتبر واتّعظ، ومن أعرض حُرِم العبرة؛ فاجعل تدبّرَ قصصِ الأنبياءِ للاعتبارِ دأبك."}},{"n":16,"reflection":{"text":"«إذ ناداه ربه بالواد المقدس طوى»: حين ناداه ربّه في الوادي المطهّرِ المباركِ (طوى)؛ ففي هذا بيانُ تشريفِ الله لموسى بالنداءِ والتكليم؛ فتأمّل كرامةَ الله لأنبيائه، واطلب القربَ من الله بالطاعة، فالله يُكرِم أهلَ طاعته، فاطلب كرامته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ كرامةِ الله لأنبيائه وطلبُ القربِ منه."},"action":{"text":"تأمّل تشريفَ موسى: إذ ناداه ربّه، أي حين كلّمه الله ونادَاه تشريفًا وتكليمًا مباشرًا، بالوادِ المقدّسِ، أي المطهّرِ المباركِ، طوًى، اسمِ ذلك الوادي بأسفلِ الطورِ في الأرضِ المقدّسة؛ فناداه الله هناك وكلّمه وكلّفه بالرسالة «إذ ناداه ربه بالواد المقدس طوى»؛ ففي هذا بيانُ تشريفِ الله لموسى عليه السلام بندائه وتكليمِه في الوادي المقدّس، وهو من كرامةِ الله لأنبيائه وأهلِ طاعته؛ فالله يُكرِم أنبياءه وأهلَ طاعته بالقربِ والتشريف؛ فتأمّل أنت كرامةَ الله لأنبيائه، واطلب أنت القربَ من الله وكرامته بالطاعةِ والإخلاصِ والعمل الصالح؛ وكلّم الله موسى تكليمًا؛ ونادَيناه من جانبِ الطورِ الأيمنِ وقرّبناه نجيًّا؛ إنّ الله اصطفى آدم ونوحًا؛ فالله يُكرِم أهلَ طاعته بالقربِ والتشريف؛ فاطلب كرامته بالطاعة، وأخلِص، واعمل؛ فمن أطاع الله وأخلص قرّبه، ومن أعرض أبعده؛ فاجعل تأمّلَ كرامةِ الله لأنبيائه وطلبَ القربِ منه دأبك."}},{"n":17,"reflection":{"text":"«اذهب إلى فرعون إنه طغى»: اذهب، يا موسى، إلى فرعونَ فأنذره، إنه تجاوز الحدَّ في الكفرِ والظلمِ والاستكبار؛ ففي هذا بيانُ الأمرِ بدعوةِ الطاغيةِ وإنذاره؛ فادعُ إلى الله ولو أعتى الناس، ولا تحابِ في الحقِّ أحدًا، فالدعوةُ تشمل الطغاة، فبلّغ الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى الله وإنذارُ الطغاةِ بلا محاباة."},"action":{"text":"تأمّل الأمرَ بالدعوة: اذهب إلى فرعونَ، أي امضِ يا موسى إلى فرعونَ فادعه إلى الله وأنذره، إنه طغى، أي تجاوز الحدَّ في الكفرِ والظلمِ والاستكبارِ والعلوِّ في الأرض، حتى ادّعى الربوبيّة؛ فأُمِر موسى بدعوةِ أعتى الخلقِ وإنذاره «اذهب إلى فرعون إنه طغى»؛ ففي هذا بيانُ أمرِ الله موسى بالذهابِ إلى فرعونَ الطاغيةِ لدعوتِه وإنذاره، مع بيانِ سببِ ذلك (طغيانه)، فالدعوةُ تشمل حتى أعتى الطغاة؛ فالدعوةُ إلى الله واجبةٌ تشمل الطغاةَ والعصاة؛ فادعُ أنت إلى الله بحكمةٍ ولو كان المدعوُّ من أعتى الناس، وأنذر الطغاةَ والعصاةَ بالحقّ، ولا تحابِ في تبليغِ الحقِّ أحدًا؛ اذهبا إلى فرعونَ إنه طغى فقولا له قولًا ليّنًا؛ اذهب إلى فرعونَ إنه طغى؛ فما على الرسولِ إلا البلاغ؛ فالدعوةُ تشمل الطغاة، والتبليغُ لا محاباةَ فيه؛ فادعُ، وأنذر، وبلّغ الحقّ؛ فمن دعا وبلّغ أدّى الأمانة، ومن سكت أثم؛ فاجعل الدعوةَ إلى الله وإنذارَ الطغاةِ دأبك."}},{"n":18,"reflection":{"text":"«فقل هل لك إلى أن تزكى»: فقل له بلطف: هل لك رغبةٌ في أن تتطهّر من دنسِ الكفرِ والمعاصي (بالإسلام)؟ ففي هذا بيانُ اللينِ والرفقِ في دعوةِ الطاغية؛ فادعُ إلى الله بالرفقِ واللينِ والترغيب، فالرفقُ في الدعوةِ أدعى للقبول، فارفق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرفقُ واللينُ في الدعوةِ إلى الله والترغيبُ في التزكية."},"action":{"text":"تأمّل رفقَ الدعوة: فقل، لفرعون، هل لك، أي هل لك رغبةٌ وميلٌ، إلى أن تزكّى، أي تتطهّر من دنسِ الكفرِ والشركِ والمعاصي، وتنمو على الخيرِ بالإيمانِ والطاعة؟ عُرِض عليه ذلك بلطفٍ ورفقٍ وترغيبٍ وتلطّفٍ في الخطاب «فقل هل لك إلى أن تزكى»؛ ففي هذا بيانُ اللينِ والرفقِ والترغيبِ في دعوةِ الطاغية، فعُرِض على فرعونَ التزكيةُ بأسلوبِ الاستفهامِ اللطيفِ الذي يستميل القلب؛ فالرفقُ واللينُ في الدعوةِ أدعى للقبول؛ فادعُ أنت إلى الله بالرفقِ واللينِ والترغيبِ وحسنِ الخطاب، ولو كان المدعوُّ طاغيًا، فإنّ الرفقَ ما كان في شيءٍ إلا زانه؛ فقولا له قولًا ليّنًا لعلّه يتذكّر أو يخشى؛ ادعُ إلى سبيلِ ربّك بالحكمةِ والموعظةِ الحسنة؛ ولو كنت فظًّا غليظَ القلبِ لانفضّوا من حولك؛ فالرفقُ في الدعوةِ أدعى للقبول، والترغيبُ يستميل القلوب؛ فارفق، ولِن، ورغّب؛ فمن رفق في الدعوةِ قُبِل منه، ومن عنّف نُفِّر عنه؛ فاجعل الرفقَ واللينَ في الدعوةِ دأبك."}},{"n":19,"reflection":{"text":"«وأهديك إلى ربك فتخشى»، وأدلّك على معرفةِ ربّك وطريقِ طاعته فتخشاه؛ ففي هذا بيانُ أنّ ثمرةَ الهدايةِ والمعرفةِ الخشيةُ؛ فاطلب معرفةَ ربّك لتخشاه، فالخشيةُ ثمرةُ المعرفة، فاعرفه لتخشاه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ معرفةِ الله التي تثمر خشيتَه."},"action":{"text":"تأمّل ثمرةَ الهداية: وأهديك إلى ربّك، أي وأدلّك وأرشدك إلى معرفةِ ربّك وتوحيدِه وطريقِ طاعته، فتخشى، أي فتخشاه وتخافه وتتّقيه؛ فالخشيةُ ثمرةُ الهدايةِ والمعرفة، فمن عرف ربّه خشيه «وأهديك إلى ربك فتخشى»؛ ففي هذا بيانُ أنّ موسى عرض على فرعونَ الهدايةَ إلى معرفةِ ربّه، وأنّ ثمرةَ تلك المعرفةِ الخشية، فمن عرف الله حقَّ معرفته خشيه؛ فالخشيةُ ثمرةُ معرفةِ الله؛ فاطلب أنت معرفةَ ربّك بأسمائه وصفاته وأفعاله، فإنّ معرفته تثمر خشيته وتقواه؛ إنما يخشى الله من عباده العلماء؛ فاعلم أنه لا إله إلا الله؛ ومن يؤمن بالله يهدِ قلبه؛ فمعرفةُ الله تثمر خشيته، والخشيةُ سبيلُ الطاعة؛ فاعرفه، واخشه، واتّقه؛ فمن عرف الله خشيه وأطاعه، ومن جهله أعرض؛ فاجعل طلبَ معرفةِ الله التي تثمر خشيتَه دأبك."}},{"n":20,"reflection":{"text":"«فأراه الآية الكبرى»: فأرى موسى فرعونَ الآيةَ العظمى (اليدَ البيضاءَ أو العصا) الدالّةَ على صدقه؛ ففي هذا بيانُ إقامةِ الحجّةِ على فرعونَ بالآيةِ البيّنة؛ فاعتبر بأنّ الله يُقيم الحجّةَ على الطغاةِ بآياته، فالحجّةُ قائمةٌ بالآيات، فاتّبع ما دلّت عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بإقامةِ الحجّةِ بالآياتِ واتّباعُها."},"action":{"text":"تأمّل إقامةَ الحجّة: فأراه، أي أرى موسى فرعونَ، الآيةَ الكبرى، أي العلامةَ العظمى المعجزةَ الدالّةَ على صدقِ رسالته وقدرةِ الله، وهي اليدُ البيضاءُ التي تخرج من جيبه بيضاءَ من غيرِ سوء، أو العصا التي انقلبت حيّةً؛ فأقام بها الحجّةَ على فرعون «فأراه الآية الكبرى»؛ ففي هذا بيانُ إقامةِ موسى الحجّةَ على فرعونَ بالآيةِ الكبرى (المعجزةِ العظمى) الدالّةِ على صدقه وقدرةِ الله؛ فالله يُقيم الحجّةَ على الطغاةِ والمكذّبين بآياته البيّنة؛ فاعتبر أنت بأنّ الله يُقيم الحجّةَ على خلقه بآياته، فاتّبع ما دلّت عليه آياتُ الله من الحقّ، ولا تكابر كما كابر فرعون؛ ولقد آتينا موسى تسعَ آياتٍ بيّنات؛ فألقى عصاه فإذا هي ثعبانٌ مبين ونزع يده فإذا هي بيضاءُ للناظرين؛ فالحجّةُ قائمةٌ بآياتِ الله، والموفّقُ من اتّبعها؛ فاعتبر بها، واتّبع الحقّ، ولا تكابر؛ فمن اتّبع الآياتِ اهتدى، ومن كابرها ضلّ؛ فاجعل الاعتبارَ بإقامةِ الحجّةِ بالآياتِ واتّباعَها دأبك."}},{"n":21,"reflection":{"text":"«فكذب وعصى»: فكذّب فرعونُ موسى بالآيةِ، وعصى الله فيما أمره؛ ففي هذا بيانُ أنّ فرعونَ قابل الحجّةَ بالتكذيبِ والعصيان؛ فاحذر أن تقابل الحقَّ بالتكذيبِ والعصيانِ كفرعون، فالتكذيبُ والعصيانُ سبيلُ الهلاك، فصدّق وأطع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ والطاعةُ عند وضوحِ الحقّ، والحذرُ من التكذيبِ والعصيان."},"action":{"text":"تأمّل مقابلةَ فرعون: فكذّب، أي كذّب فرعونُ موسى وآيتَه ورسالته، وردّ الحقَّ بعد وضوحه، وعصى، أي عصى الله فيما أمره به على لسانِ موسى، وأبى الانقياد؛ فقابل الحجّةَ البيّنةَ بالتكذيبِ والعصيانِ كبرًا وعنادًا «فكذب وعصى»؛ ففي هذا بيانُ أنّ فرعونَ قابل الآيةَ الكبرى والحجّةَ البيّنةَ بالتكذيبِ (بالقلبِ واللسان) والعصيانِ (بالجوارح)، فجمع بين ضدّي التصديقِ والطاعة؛ فالتكذيبُ والعصيانُ سبيلُ الطغاةِ وموجبُ الهلاك؛ فاحذر أنت أن تقابل الحقَّ إذا تبيّن لك بالتكذيبِ والعصيانِ كما فعل فرعون، بل صدّق وأطع؛ ثم أدبر واستكبر فقال إن هذا إلا سحرٌ يؤثر؛ وجحدوا بها واستيقنتها أنفسهم؛ فكذّبوه فعقروها؛ فالتكذيبُ والعصيانُ سبيلُ الهلاك، والتصديقُ والطاعةُ سبيلُ النجاة؛ فصدّق، وأطع، ولا تكابر؛ فمن صدّق وأطاع نجا، ومن كذّب وعصى هلك؛ فاجعل التصديقَ والطاعةَ والحذرَ من التكذيبِ والعصيانِ دأبك."}},{"n":22,"reflection":{"text":"«ثم أدبر يسعى»: ثم ولّى فرعونُ معرضًا عن الحقّ، يسعى في معارضةِ موسى وإبطالِ دعوته؛ ففي هذا بيانُ سعيِ فرعونَ في محاربةِ الحقّ بعد إعراضه؛ فاحذر أن تسعى في محاربةِ الحقّ، بل اسعَ في نصرته، فالسعيُ في محاربةِ الحقِّ هلكة، فاسعَ في الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"السعيُ في نصرةِ الحقّ لا في محاربته."},"action":{"text":"تأمّل سعيَه في الباطل: ثم أدبر، أي ولّى معرضًا عن الحقِّ والإيمان، يسعى، أي يسعى ويجدّ في معارضةِ موسى، وجمعِ السحرةِ، والكيدِ لدعوته، والصدِّ عنها، والإفسادِ في الأرض؛ فسخّر سعيه لمحاربةِ الحقّ «ثم أدبر يسعى»؛ ففي هذا بيانُ أنّ فرعونَ بعد إعراضه سعى وجدّ في محاربةِ الحقِّ وإبطالِ دعوةِ موسى، فسخّر جهده وسعيه للباطل؛ فالسعيُ في محاربةِ الحقِّ سبيلُ الطغاةِ وموجبُ الهلاك؛ فاحذر أنت أن تسعى في محاربةِ الحقِّ والصدِّ عنه، بل اسعَ في نصرةِ الحقِّ ونشرِه والدعوةِ إليه؛ وإذا تولّى سعى في الأرضِ ليفسد فيها؛ الذين يصدّون عن سبيلِ الله ويبغونها عوجًا؛ ومن الناسِ من يشري نفسه ابتغاءَ مرضاةِ الله؛ فالسعيُ في محاربةِ الحقِّ هلكة، والسعيُ في نصرته نجاة؛ فاسعَ في الحقّ، وانصره، ولا تحاربه؛ فمن سعى في نصرةِ الحقِّ أفلح، ومن سعى في محاربته هلك؛ فاجعل السعيَ في نصرةِ الحقِّ دأبك."}},{"n":23,"reflection":{"text":"«فحشر فنادى»: فجمع فرعونُ قومه وسحرته وجنوده، فنادى فيهم بدعوته الباطلة؛ ففي هذا بيانُ جمعِ فرعونَ لأعوانه على الباطل؛ فاحذر أن تجمع الناسَ على باطل، بل اجمعهم على الحقّ، فجمعُ الناسِ على الباطلِ إثم، فاجمعهم على الخير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"جمعُ الناسِ على الحقِّ والخير، والحذرُ من جمعهم على الباطل."},"action":{"text":"تأمّل جمعَه على الباطل: فحشر، أي جمع فرعونُ قومه وسحرته وجنوده وأشرافَ مملكته، فنادى، أي نادى فيهم بصوتٍ عالٍ، أو أمر مناديًا ينادي، معلنًا دعوته الباطلةَ وتحدّيه «فحشر فنادى»؛ ففي هذا بيانُ أنّ فرعونَ جمع أعوانه وحشد قومه ونادى فيهم، مستعينًا بهم على محاربةِ الحقّ، ومعلنًا دعواه الباطلة؛ فجمعُ الناسِ على الباطلِ من سعيِ الطغاة؛ فاحذر أنت أن تجمع الناسَ أو تحشدهم على باطلٍ أو ظلمٍ أو ضلال، بل اجمعهم وادعُهم إلى الحقِّ والخيرِ والهدى؛ فجمع كيده ثم أتى؛ فأرسل فرعونُ في المدائنِ حاشرين؛ واجعلنا للمتّقين إمامًا؛ فجمعُ الناسِ على الباطلِ إثمٌ وضلال، وجمعُهم على الحقِّ خيرٌ وهدى؛ فاجمعهم على الخير، وادعهم إلى الحقّ، ولا تحشدهم على باطل؛ فمن جمع الناسَ على الحقِّ أُجِر، ومن جمعهم على الباطلِ أثم؛ فاجعل جمعَ الناسِ على الحقِّ والخيرِ دأبك."}},{"n":24,"reflection":{"text":"«فقال أنا ربكم الأعلى»: فقال فرعونُ لقومه: أنا ربّكم الأعلى (فبلغ الغايةَ في الطغيانِ وادّعاءِ الربوبيّة)؛ ففي هذا بيانُ منتهى طغيانِ فرعونَ بدعوى الربوبيّة؛ فاحذر الكبرَ والطغيانَ اللذين بلغا بفرعونَ دعوى الربوبيّة، فالكبرُ يُرِدي صاحبه، فتواضع لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لله والحذرُ من الكبرِ والطغيان."},"action":{"text":"تأمّل منتهى طغيانه: فقال، فرعونُ لقومه، أنا ربّكم الأعلى، أي أنا إلهكم ومعبودكم الأعلى الذي لا ربَّ فوقي؛ فبلغ الغايةَ القصوى في الطغيانِ والكبرِ والكفر، حيث ادّعى الربوبيّةَ والألوهيّةَ لنفسه، ولا أطغى من هذا «فقال أنا ربكم الأعلى»؛ ففي هذا بيانُ منتهى طغيانِ فرعونَ وكبرِه، إذ ادّعى الربوبيّةَ لنفسه، وهو غايةُ ما يبلغه الطغيانُ والكبر؛ فالكبرُ والطغيانُ قد يُرديان صاحبهما إلى أعظمِ الكفر؛ فاحذر أنت الكبرَ والطغيانَ اللذين بلغا بفرعونَ دعوى الربوبيّة، فإنّ الكبرَ بريدُ الهلاك، وتواضع لله واعبده وحده؛ ما علمتُ لكم من إلهٍ غيري؛ فحشر فنادى فقال أنا ربّكم الأعلى؛ إنّ الذين يستكبرون عن عبادتي سيدخلون جهنّم داخرين؛ فالكبرُ والطغيانُ يُرديان، والتواضعُ لله سبيلُ النجاة؛ فتواضع، واعبد الله وحده، واحذر الكبر؛ فمن تواضع لله عزّ، ومن تكبّر وطغى هلك؛ فاجعل التواضعَ لله والحذرَ من الكبرِ والطغيانِ دأبك."}},{"n":25,"reflection":{"text":"«فأخذه الله نكال الآخرة والأولى»: فأخذه الله أخذَ عزيزٍ مقتدر، فعاقبه عقوبةَ الآخرةِ (النار) والأولى (الغرقِ في الدنيا) عبرةً؛ ففي هذا بيانُ عاقبةِ الطغيان: الأخذُ في الدنيا والآخرة؛ فاحذر الطغيانَ الذي عاقبته النكالُ في الدارين، فعاقبةُ الطغيانِ نكالٌ، فاتّقه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الطغيانِ الذي عاقبته النكالُ في الدنيا والآخرة."},"action":{"text":"تأمّل عاقبةَ فرعون: فأخذه الله، أي عاقبه وانتقم منه أخذَ عزيزٍ مقتدر، نكالَ الآخرةِ والأولى، أي جعله عبرةً ونكالًا: عذّبه في الآخرةِ بالنار، وعذّبه في الأولى (الدنيا) بالغرقِ في اليمّ؛ أو نكّل به نكالَ كلمتِه الآخرةِ (أنا ربّكم الأعلى) والأولى (ما علمتُ لكم من إلهٍ غيري)؛ فأخذه الله أخذًا وبيلًا «فأخذه الله نكال الآخرة والأولى»؛ ففي هذا بيانُ عاقبةِ طغيانِ فرعون: أنّ الله أخذه وعاقبه عقوبةً في الدنيا (الغرق) والآخرة (النار)، جعله بها نكالًا وعبرةً لغيره؛ فعاقبةُ الطغيانِ النكالُ في الدارين؛ فاحذر أنت الطغيانَ والكبرَ الذي عاقبته النكالُ في الدنيا والآخرة، واعتبر بفرعون؛ فأخذناه وجنودَه فنبذناهم في اليمّ؛ فأخذهم الله بذنوبهم؛ ويومَ القيامةِ يقدم قومه فأوردهم النار؛ فعاقبةُ الطغيانِ نكالٌ في الدارين، والاعتبارُ به واجب؛ فاتّقِ الطغيان، واعتبر بفرعون، وتواضع؛ فمن اتّقى نجا، ومن طغى أُخِذ نكالًا؛ فاجعل الحذرَ من الطغيانِ الذي عاقبته النكالُ دأبك."}},{"n":26,"reflection":{"text":"«إن في ذلك لعبرة لمن يخشى»: إنّ في قصّةِ فرعونَ (طغيانِه وأخذِه) لعبرةً وعظةً لمن يخشى الله؛ ففي هذا بيانُ أنّ الاعتبارَ بالقصصِ إنما ينتفع به أهلُ الخشية؛ فاعتبر بقصّةِ فرعونَ فإنّ العبرةَ لمن يخشى، فالخشيةُ تفتح بابَ الاعتبار، فاخش الله لتعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالقصصِ بخشيةِ الله."},"action":{"text":"تأمّل موضعَ العبرة: إنّ في ذلك، أي في قصّةِ موسى وفرعونَ، وطغيانِ فرعونَ وأخذِه نكالًا، لعبرةً، أي لعظةً وموعظةً وعبرةً يُعتبَر بها، لمن يخشى، أي لمن يخشى الله ويخاف عقابه، فهو الذي ينتفع بالعبرةِ ويتّعظ، بخلافِ الغافلِ القاسي «إن في ذلك لعبرة لمن يخشى»؛ ففي هذا بيانُ أنّ في قصّةِ فرعونَ عبرةً وعظةً، وأنّ المنتفعَ بها هو من يخشى الله، فإنّ الخشيةَ تفتح بابَ الاعتبارِ والاتّعاظ؛ فالاعتبارُ بالقصصِ إنما ينتفع به أهلُ الخشية؛ فاخش أنت الله لتنتفع بالعبرِ والمواعظ، واعتبر بقصّةِ فرعونَ وعاقبةِ طغيانه، فإنّ من خشي الله اتّعظ واعتبر؛ إنما يخشى الله من عباده العلماء؛ سيذّكّر من يخشى؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ فالعبرةُ لمن يخشى، والخشيةُ سبيلُ الاعتبار؛ فاخش الله، واعتبر، واتّعظ؛ فمن خشي الله اعتبر واتّعظ، ومن غفل قسا؛ فاجعل الاعتبارَ بالقصصِ بخشيةِ الله دأبك."}}]},{"title":"الاستدلالُ بخلقِ السماءِ والأرضِ على البعث","range":[27,33],"theme":"الاستدلالُ بخلقِ السماء «أأنتم أشد خلقا أم السماء بناها رفع سمكها فسواها وأغطش ليلها وأخرج ضحاها»، ودحوِ الأرضِ ونعمِها «والأرض بعد ذلك دحاها أخرج منها ماءها ومرعاها والجبال أرساها متاعا لكم ولأنعامكم»","verses":[{"n":27,"reflection":{"text":"«أأنتم أشد خلقا أم السماء بناها»: أخلقكم، أيها المنكرون للبعث، أشدُّ وأصعبُ أم خلقُ السماءِ التي بناها الله؟ ففي هذا بيانُ أنّ خلقَ السماءِ أعظمُ من خلقِ الناس، فمن قدر عليه قدر على البعث؛ فأيقن بقدرةٍ خلقت السماءَ على بعثك، فمن بنى السماءَ يبعثك، فأيقن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله على البعثِ بالاستدلالِ بخلقِ السماء."},"action":{"text":"تأمّل الاستدلالَ بالسماء: أأنتم، أيها المنكرون للبعثِ المستبعدون له، أشدُّ خلقًا، أي أصعبُ وأعظمُ خلقًا وإعادةً، أم السماءُ، أي أم خلقُ السماءِ العظيمةِ، بناها، أي بناها الله ورفعها؟ والجوابُ: خلقُ السماءِ أعظمُ وأشدّ، فمن قدر على خلقها قدر على بعثكم من بابِ أولى «أأنتم أشد خلقا أم السماء بناها»؛ ففي هذا بيانُ الاستدلالِ على قدرةِ الله على البعثِ بخلقِ السماءِ العظيمة، فإنّ خلقها أعظمُ من خلقِ الناسِ وإعادتهم، فمن قدر على الأعظمِ قدر على الأدنى؛ فخلقُ السماءِ أعظمُ من البعث، فمن قدر عليه قدر على البعث؛ فأيقن أنت بقدرةِ الله على بعثك، مستدلًّا بخلقِ السماءِ العظيمة، فالذي بناها قادرٌ على إعادتك؛ لخلقُ السماواتِ والأرضِ أكبرُ من خلقِ الناس؛ أوليس الذي خلق السماواتِ والأرضَ بقادرٍ على أن يخلق مثلهم بلى؛ فخلقُ السماءِ برهانٌ على القدرةِ على البعث؛ فأيقن به، ولا تستبعده، واستعدّ؛ فمن أيقن بالبعثِ استعدّ، ومن استبعده جهل؛ فاجعل اليقينَ بقدرةِ الله على البعثِ دأبك."}},{"n":28,"reflection":{"text":"«رفع سمكها فسواها»: رفع الله ارتفاعَها وأعلى بناءها، فسوّاها محكمةً لا عيبَ فيها؛ ففي هذا بيانُ عظمةِ قدرةِ الله في رفعِ السماءِ وتسويتها؛ فتأمّل رفعَ السماءِ وإحكامَها آيةً على قدرةِ الله، فمن سوّى السماءَ يبعثك، فأيقن واعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ برفعِ السماءِ وإحكامِها آيةً على القدرة."},"action":{"text":"تأمّل رفعَ السماء: رفع سمكها، أي رفع ارتفاعها وأعلى بناءها في الهواءِ بلا عمد، فسوّاها، أي جعلها مستويةً محكمةً متقنةً لا شقوقَ فيها ولا فطورَ ولا عيب، معتدلةَ الخلق «رفع سمكها فسواها»؛ ففي هذا بيانُ عظمةِ قدرةِ الله في رفعِ السماءِ إلى ذلك الارتفاعِ العظيمِ وتسويتها وإحكامها بلا عمدٍ ولا خلل، وهي آيةٌ على قدرته وقدرته على البعث؛ فرفعُ السماءِ وإحكامُها آيةٌ على عظمةِ القدرة؛ فتأمّل أنت رفعَ السماءِ وإحكامَها وإتقانها، واستدلّ بها على قدرةِ الله وعظمته وقدرته على بعثك؛ الذي خلق سبعَ سماواتٍ طباقًا ما ترى في خلقِ الرحمنِ من تفاوت؛ والسماءَ بنيناها بأيدٍ وإنا لموسعون؛ أفلم ينظروا إلى السماءِ فوقهم كيف بنيناها؛ فرفعُ السماءِ وإحكامُها آيةٌ على القدرةِ والبعث؛ فتأمّلها، واعتبر بها، وأيقن؛ فمن اعتبر بها أيقن، ومن غفل جهل؛ فاجعل الاعتبارَ برفعِ السماءِ آيةً على القدرةِ دأبك."}},{"n":29,"reflection":{"text":"«وأغطش ليلها وأخرج ضحاها»، وأظلم ليلها فجعله مظلمًا، وأخرج ضوءَ نهارها؛ ففي هذا بيانُ نعمةِ تعاقبِ الليلِ والنهارِ آيةً على قدرةِ الله؛ فاشكر نعمةَ الليلِ والنهارِ واستدلّ بها على قدرةِ الله، فتعاقبهما نعمةٌ وآية، فاشكر واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ تعاقبِ الليلِ والنهارِ والاستدلالُ بها على القدرة."},"action":{"text":"تأمّل تعاقبَ الليلِ والنهار: وأغطش ليلها، أي أظلم ليلَ السماءِ فجعله مظلمًا ساترًا، تسكن فيه الخلق، وأخرج ضحاها، أي أظهر ضوءَ نهارها وأبرز شمسها وضياءها، ينتشر فيه الناسُ لمعاشهم؛ فجعل فيها الليلَ والنهارَ بحكمةٍ وقدرة «وأغطش ليلها وأخرج ضحاها»؛ ففي هذا بيانُ نعمةِ الله في جعلِ الليلِ مظلمًا للسكنِ والراحة، والنهارِ مضيئًا للمعاشِ والسعي، وما في تعاقبهما من الحكمةِ والقدرة والرحمة، وهي آيةٌ على قدرته وقدرته على البعث؛ فتعاقبُ الليلِ والنهارِ نعمةٌ وآيةٌ على القدرة؛ فاشكر أنت نعمةَ الليلِ والنهارِ وتعاقبهما، واستدلّ بها على قدرةِ الله وحكمته ورحمته وقدرته على البعث؛ وجعلنا الليلَ والنهارَ آيتين فمحونا آيةَ الليلِ وجعلنا آيةَ النهارِ مبصرة؛ يُغشي الليلَ النهارَ يطلبه حثيثًا؛ فتعاقبُ الليلِ والنهارِ نعمةٌ وآيةٌ تستوجب الشكرَ والاعتبار؛ فاشكرها، واعتبر بها، وأيقن؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ الليلِ والنهارِ والاستدلالَ بها دأبك."}},{"n":30,"reflection":{"text":"«والأرض بعد ذلك دحاها»، والأرضَ بعد خلقِ السماءِ بسطها ومدّها ومهّدها للسكنى؛ ففي هذا بيانُ نعمةِ دحوِ الأرضِ آيةً على قدرةِ الله ورحمته؛ فاشكر نعمةَ الأرضِ المدحوّةِ واستدلّ بها على قدرةِ الله، فدحوُ الأرضِ نعمةٌ وآية، فاشكر واعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ دحوِ الأرضِ والاستدلالُ بها على القدرة."},"action":{"text":"تأمّل دحوَ الأرض: والأرضَ بعد ذلك، أي بعد خلقِ السماءِ (أو مع ذلك، فالدحوُ غيرُ الخلق)، ودحاها، أي بسطها ومدّها ومهّدها وهيّأها للسكنى والانتفاع، وأودع فيها منافعها؛ فدحوُ الأرضِ: بسطها وتمهيدها «والأرض بعد ذلك دحاها»؛ ففي هذا بيانُ نعمةِ الله في دحوِ الأرضِ (بسطها وتمهيدها) بعد خلقها، لتكون صالحةً للسكنى والزرعِ والانتفاع، وهي آيةٌ على قدرته ورحمته وقدرته على البعث؛ فدحوُ الأرضِ نعمةٌ وآيةٌ على القدرةِ والرحمة؛ فاشكر أنت نعمةَ الأرضِ المدحوّةِ الممهّدةِ التي تسكنها وتنتفع بها، واستدلّ بها على قدرةِ الله ورحمته وقدرته على البعث؛ وهو الذي مدّ الأرضَ وجعل فيها رواسيَ وأنهارًا؛ والأرضَ مددناها وألقينا فيها رواسي؛ والأرضَ فرشناها فنعم الماهدون؛ فدحوُ الأرضِ نعمةٌ وآيةٌ تستوجب الشكرَ والاعتبار؛ فاشكرها، واعتبر بها؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ دحوِ الأرضِ والاستدلالَ بها دأبك."}},{"n":31,"reflection":{"text":"«أخرج منها ماءها ومرعاها»: أخرج من الأرضِ ماءها (العيونَ والأنهار) ومرعاها (النباتَ والكلأ)؛ ففي هذا بيانُ نعمةِ الماءِ والمرعى آيةً على رحمةِ الله وقدرته؛ فاشكر نعمةَ الماءِ والمرعى واستدلّ بها على قدرةِ الله على البعث، فإخراجُ الماءِ والمرعى نعمةٌ وآية، فاشكر واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الماءِ والمرعى والاستدلالُ بها على البعث."},"action":{"text":"تأمّل إخراجَ الماءِ والمرعى: أخرج منها، من الأرضِ بعد دحوها، ماءها، أي فجّر فيها العيونَ والأنهارَ وأنبع الماء، ومرعاها، أي أنبت فيها النباتَ والكلأَ والزرعَ والشجرَ الذي يُرعى ويُؤكَل؛ فأخرج منها الماءَ والمرعى قوامًا للحياة «أخرج منها ماءها ومرعاها»؛ ففي هذا بيانُ نعمةِ الله في إخراجِ الماءِ والمرعى من الأرضِ بعد دحوها، وما فيهما من قوامِ حياةِ الناسِ والأنعام، وهي آيةٌ على قدرته ورحمته وقدرته على البعثِ (إحياءِ الأرضِ كإحياءِ الموتى)؛ فإخراجُ الماءِ والمرعى نعمةٌ وآيةٌ على الرحمةِ والبعث؛ فاشكر أنت نعمةَ الماءِ والمرعى، واستدلّ بها على قدرةِ الله ورحمته وقدرته على إحياءِ الموتى؛ فلينظر الإنسانُ إلى طعامه؛ فأخرجنا به نباتَ كلِّ شيء؛ وآيةٌ لهم الأرضُ الميتةُ أحييناها؛ فإخراجُ الماءِ والمرعى نعمةٌ وآيةٌ على الرحمةِ والبعث؛ فاشكرها، واعتبر بها، وأيقن؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ الماءِ والمرعى والاستدلالَ بها دأبك."}},{"n":32,"reflection":{"text":"«والجبال أرساها»، والجبالَ أثبتها وأرساها في الأرضِ لتقرّ ولا تميد؛ ففي هذا بيانُ نعمةِ إرساءِ الجبالِ آيةً على قدرةِ الله وحكمته؛ فاشكر نعمةَ الجبالِ التي تثبّت الأرضَ واستدلّ بها على قدرةِ الله، فإرساءُ الجبالِ نعمةٌ وآية، فاشكر واعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ إرساءِ الجبالِ والاستدلالُ بها على القدرة."},"action":{"text":"تأمّل إرساءَ الجبال: والجبالَ أرساها، أي أثبتها وثبّتها في الأرضِ وجعلها راسياتٍ ثوابتَ تُرسي الأرضَ وتمنعها أن تميد وتضطرب بأهلها؛ فأرساها أوتادًا للأرض «والجبال أرساها»؛ ففي هذا بيانُ نعمةِ الله في إرساءِ الجبالِ وتثبيتها في الأرض، لتقرّ الأرضُ ولا تميد، وما في ذلك من الحكمةِ والقدرة، وهي آيةٌ على قدرته وقدرته على البعث؛ فإرساءُ الجبالِ نعمةٌ وآيةٌ على القدرةِ والحكمة؛ فاشكر أنت نعمةَ الجبالِ التي تثبّت الأرضَ وتُقِرّها، واستدلّ بها على قدرةِ الله وحكمته وقدرته على البعث؛ وألقى في الأرضِ رواسيَ أن تميد بكم؛ والجبالَ أوتادًا؛ وجعلنا فيها رواسيَ شامخات؛ فإرساءُ الجبالِ نعمةٌ وآيةٌ تستوجب الشكرَ والاعتبار؛ فاشكرها، واعتبر بها؛ فمن شكر واعتبر اهتدى، ومن غفل كفر؛ فاجعل شكرَ نعمةِ إرساءِ الجبالِ والاستدلالَ بها دأبك."}},{"n":33,"reflection":{"text":"«متاعا لكم ولأنعامكم»: جعل ذلك كلَّه (الماءَ والمرعى والجبال) متاعًا ومنفعةً لكم ولأنعامكم؛ ففي هذا بيانُ أنّ نعمَ الأرضِ متاعٌ للإنسانِ والحيوان؛ فاشكر نعمَ الله التي جعلها متاعًا لك ولأنعامك، ووظّفها في طاعته، فنعمُ الله متاعٌ للشكر، فاشكرها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله وتوظيفُها في طاعته."},"action":{"text":"تأمّل غايةَ النعم: متاعًا لكم، أي جعل الله ذلك كلَّه (دحوَ الأرضِ وإخراجَ الماءِ والمرعى وإرساءَ الجبال) متاعًا ومنفعةً وبلغةً لكم، أيها الناسُ، ولأنعامكم، أي وللأنعامِ التي تنتفعون بها؛ فكلُّ ذلك نعمةٌ ومتاعٌ لمنفعتكم ومنفعةِ أنعامكم «متاعا لكم ولأنعامكم»؛ ففي هذا بيانُ أنّ الله جعل نعمَ الأرضِ (الماءَ والمرعى والجبالَ وغيرها) متاعًا ومنفعةً للإنسانِ وأنعامِه، رحمةً بهم، فتستوجب الشكر؛ فنعمُ الله متاعٌ ومنفعةٌ تستوجب الشكرَ والطاعة؛ فاشكر أنت نعمَ الله التي جعلها متاعًا لك ولأنعامك، ووظّفها في طاعته لا في معصيته، ولا تكفرها ولا تطغَ بها؛ كلوا وارعوا أنعامكم؛ فاكهةً وأبًّا متاعًا لكم ولأنعامكم؛ ومن آياته أن خلق لكم من أنفسكم؛ فنعمُ الله متاعٌ للانتفاعِ والشكر؛ فاشكرها، ووظّفها في الطاعة، ولا تكفرها؛ فمن شكر النعمَ ووظّفها في الطاعةِ بورك له، ومن كفرها أُخِذ؛ فاجعل شكرَ نعمِ الله وتوظيفَها في طاعته دأبك."}}]},{"title":"الطامّةُ الكبرى وانقسامُ الناسِ وعلمُ الساعةِ لله","range":[34,46],"theme":"مجيءُ الطامّة «فإذا جاءت الطامة الكبرى يوم يتذكر الإنسان ما سعى وبرزت الجحيم لمن يرى»، وانقسامِ الناس «فأما من طغى وآثر الحياة الدنيا فإن الجحيم هي المأوى وأما من خاف مقام ربه ونهى النفس عن الهوى فإن الجنة هي المأوى»، وأنّ علمَ الساعةِ لله «يسألونك عن الساعة أيان مرساها... إلى ربك منتهاها إنما أنت منذر من يخشاها»، وقصرِ الدنيا «كأنهم يوم يرونها لم يلبثوا إلا عشية أو ضحاها»","verses":[{"n":34,"reflection":{"text":"«فإذا جاءت الطامة الكبرى»: فإذا جاءت الداهيةُ العظمى التي تطمّ على كلِّ شيءٍ وتغلبه (القيامةُ الكبرى)؛ ففي هذا بيانُ عظمِ هولِ القيامةِ التي تغلب كلَّ هول؛ فاستعدّ للطامّةِ الكبرى التي تطمّ على كلِّ شيء، فالقيامةُ داهيةٌ عظمى، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للطامّةِ الكبرى (القيامة)."},"action":{"text":"تأمّل الطامّة: فإذا جاءت الطامّةُ الكبرى، أي فإذا جاءت الداهيةُ العظمى التي تطمّ وتعلو على كلِّ شيءٍ وتغلبه وتغمره، وهي القيامةُ ونفخةُ البعث، أو النفخةُ التي يُساق بها الخلقُ إلى الجنّةِ أو النار؛ سُمّيت طامّةً لأنها تطمّ على كلِّ هائلةٍ فتغلبها «فإذا جاءت الطامة الكبرى»؛ ففي هذا بيانُ عظمِ هولِ القيامة، وأنها الطامّةُ الكبرى التي تغلب كلَّ هولٍ وتعلو على كلِّ داهية؛ فالقيامةُ داهيةٌ عظمى تطمّ على كلِّ شيء؛ فاستعدّ أنت للطامّةِ الكبرى (القيامة) التي تطمّ على كلِّ شيء، بالإيمانِ والعملِ الصالحِ قبل مجيئها؛ فإذا جاءت الصاخّة؛ يومَ التنادِ يومَ تولّون مدبرين؛ القارعةُ ما القارعة؛ فالقيامةُ طامّةٌ كبرى تغلب كلَّ هول، فالاستعدادُ لها واجب؛ فاستعدّ، واعمل، ولا تسوّف؛ فمن استعدّ لها أمِن، ومن غفل فوجئ؛ فاجعل الاستعدادَ للطامّةِ الكبرى دأبك."}},{"n":35,"reflection":{"text":"«يوم يتذكر الإنسان ما سعى»: يومَ يتذكّر الإنسانُ كلَّ ما عمله وسعاه من خيرٍ أو شرّ؛ ففي هذا بيانُ تذكّرِ الإنسانِ أعمالَه يومَ القيامة؛ فاعمل صالحًا تسرّ بتذكّره يومَ القيامة، فالسعيُ يُتذكَّر يومئذٍ، فأحسِن سعيك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إحسانُ السعيِ ليُتذكَّر بسرورٍ يومَ القيامة."},"action":{"text":"تأمّل تذكّرَ السعي: يومَ يتذكّر الإنسانُ، عند مجيءِ الطامّةِ الكبرى، ما سعى، أي يتذكّر كلَّ ما عمله وسعاه في الدنيا من خيرٍ أو شرّ، فيراه حاضرًا في صحيفته، بعد أن كان نسيه؛ فيتذكّر عمله كلَّه يومَ لا ينفع التذكّر إن كان سوءًا «يوم يتذكر الإنسان ما سعى»؛ ففي هذا بيانُ أنّ الإنسانَ يومَ القيامةِ يتذكّر جميعَ أعماله وسعيه، فيسرّ المحسنُ بعمله ويندم المسيء؛ فالسعيُ كلُّه يُتذكَّر ويُرى يومَ القيامة؛ فاعمل أنت صالحًا تسرّ بتذكّره ورؤيته يومَ القيامة، واحذر السيّئَ الذي تندم على تذكّره، فأحسِن سعيك؛ ووجدوا ما عملوا حاضرًا؛ يومئذٍ يتذكّر الإنسانُ وأنّى له الذكرى؛ يومَ تجد كلُّ نفسٍ ما عملت من خيرٍ محضرًا؛ فالسعيُ يُتذكَّر يومَ القيامة، فالعاقلُ من أحسن سعيه؛ فأحسِن سعيك، واحذر السيّئ، واستعدّ؛ فمن أحسن سعيه سُرّ، ومن أساءه ندم؛ فاجعل إحسانَ السعيِ ليُتذكَّر بسرورٍ دأبك."}},{"n":36,"reflection":{"text":"«وبرزت الجحيم لمن يرى»، وأُظهِرت جهنّمُ وكُشِفت لكلِّ ناظرٍ يراها؛ ففي هذا بيانُ إبرازِ الجحيمِ يومَ القيامةِ للعيان؛ فاحذر نارًا تُبرَز للعيانِ يومَ القيامة، فالجحيمُ تُبرَز للناظرين، فاعمل لِما ينجّيك منها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الجحيمِ التي تُبرَز، والعملُ للنجاةِ منها."},"action":{"text":"تأمّل إبرازَ الجحيم: وبُرِّزت الجحيمُ، أي أُظهِرت جهنّمُ وكُشِف عنها الغطاءُ وأُبرِزت للعيان، لمن يرى، أي لكلِّ ناظرٍ يراها، يراها الخلائقُ عِيانًا في الموقف؛ فتظهر لهم فيفزعون منها «وبرزت الجحيم لمن يرى»؛ ففي هذا بيانُ أنّ جهنّمَ تُبرَز وتُظهَر يومَ القيامةِ للعيان، فيراها الخلائقُ رأيَ العينِ في الموقف، فيزداد فزعُ المكذّبين؛ فالجحيمُ تُبرَز للعيانِ يومَ القيامة؛ فاحذر أنت نارًا تُبرَز وتُكشَف للعيانِ يومَ القيامة، واعمل لِما ينجّيك منها من الإيمانِ والتقوى والعملِ الصالح؛ وبُرِّزت الجحيمُ للغاوين؛ وإذا الجحيمُ سُعِّرت؛ وجيء يومئذٍ بجهنّم؛ فالجحيمُ تُبرَز للناظرين، والنجاةُ منها بالعمل؛ فاعمل للنجاة، وآمن، واتّقِ؛ فمن اتّقى نجا منها، ومن طغى ورَدها؛ فاجعل الحذرَ من الجحيمِ والعملَ للنجاةِ منها دأبك."}},{"n":37,"reflection":{"text":"«فأما من طغى»: فأما من تجاوز الحدَّ في الكفرِ والمعاصي والظلم؛ ففي هذا بيانُ أوّلِ وصفي أهلِ الشقاء: الطغيان؛ فاحذر الطغيانَ الذي هو أوّلُ سببِ الشقاء، فالطغيانُ سبيلُ النار، فاتّقه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الطغيانِ الذي هو سببُ الشقاء."},"action":{"text":"تأمّل أوّلَ وصفِ الأشقياء: فأما من طغى، أي فأما من تجاوز الحدَّ في الكفرِ والعصيانِ والظلمِ والاستكبار، وتمرّد على أمرِ الله، وتعدّى حدوده؛ فالطغيانُ مجاوزةُ الحدِّ في الشرّ «فأما من طغى»؛ ففي هذا بيانُ أوّلِ وصفي أهلِ الشقاءِ الذين مأواهم النار: الطغيانِ ومجاوزةِ الحدِّ في الكفرِ والمعصية؛ فالطغيانُ أوّلُ أسبابِ الشقاءِ والنار؛ فاحذر أنت الطغيانَ ومجاوزةَ حدودِ الله في الكفرِ والمعاصي والظلم، فإنه سبيلُ النار، والزم حدودَ الله؛ فأما من طغى وآثر الحياةَ الدنيا فإنّ الجحيمَ هي المأوى؛ إنّ الإنسانَ ليطغى؛ كلّا إنّ الإنسانَ ليطغى أن رآه استغنى؛ فالطغيانُ سبيلُ النار، ولزومُ حدودِ الله سبيلُ النجاة؛ فاتّقِ الطغيان، والزم الحدود؛ فمن اتّقى الطغيانَ نجا، ومن طغى شقي؛ فاجعل الحذرَ من الطغيانِ دأبك."}},{"n":38,"reflection":{"text":"«وآثر الحياة الدنيا»، وقدّم الحياةَ الدنيا وشهواتِها على الآخرةِ وعملِها؛ ففي هذا بيانُ ثاني وصفي أهلِ الشقاء: إيثارِ الدنيا؛ فاحذر إيثارَ الدنيا على الآخرة، بل آثِر الباقية، فإيثارُ الدنيا سبيلُ الشقاء، فآثِر الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ الآخرةِ على الدنيا، والحذرُ من إيثارِ العاجلة."},"action":{"text":"تأمّل ثانيَ وصفِ الأشقياء: وآثر الحياةَ الدنيا، أي قدّم الحياةَ الدنيا وشهواتِها ولذّاتِها العاجلةَ على الآخرةِ وعملِها الباقي، فجعل الدنيا أكبرَ همّه ومبلغَ علمه، وترك العملَ للآخرة؛ فآثر الفانيَ على الباقي «وآثر الحياة الدنيا»؛ ففي هذا بيانُ ثاني وصفي أهلِ الشقاء: إيثارِ الحياةِ الدنيا على الآخرة، فمن طغى وآثر الدنيا فقد جمع بين سببي الشقاء؛ فإيثارُ الدنيا على الآخرةِ سبيلُ الشقاء؛ فاحذر أنت إيثارَ الدنيا وشهواتِها على الآخرةِ وعملها، بل آثِر الآخرةَ الباقيةَ على الدنيا الفانية، واجعل الدنيا في يدك لا في قلبك؛ بل تؤثرون الحياةَ الدنيا والآخرةُ خيرٌ وأبقى؛ من كان يريد العاجلةَ عجّلنا له فيها؛ يحبّون العاجلةَ ويذرون وراءهم يومًا ثقيلًا؛ فإيثارُ الدنيا سبيلُ الشقاء، وإيثارُ الآخرةِ سبيلُ النجاة؛ فآثِر الآخرة، ولا تؤثر العاجلة؛ فمن آثر الآخرةَ سعد، ومن آثر الدنيا شقي؛ فاجعل إيثارَ الآخرةِ على الدنيا دأبك."}},{"n":39,"reflection":{"text":"«فإن الجحيم هي المأوى»: فإنّ جهنّمَ هي مأواه ومسكنه (جزاءَ طغيانه وإيثارِه الدنيا)؛ ففي هذا بيانُ أنّ مأوى الطاغي المؤثِرِ للدنيا النار؛ فاحذر أن يكون مأواك النارَ بالطغيانِ وإيثارِ الدنيا، فمأوى هذين النار، فاتّقِ سببهما.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يكون المأوى النارَ بالطغيانِ وإيثارِ الدنيا."},"action":{"text":"تأمّل مأوى الأشقياء: فإنّ الجحيم، جهنّم، هي المأوى، أي هي مأواه ومسكنه ومقرّه الذي يأوي إليه، جزاءَ طغيانه وإيثارِه الحياةَ الدنيا؛ فمن جمع الطغيانَ وإيثارَ الدنيا كان مأواه النار «فإن الجحيم هي المأوى»؛ ففي هذا بيانُ أنّ مأوى من طغى وآثر الحياةَ الدنيا هو الجحيم، فهي مسكنه ومقرّه، جزاءَ وصفيه؛ فمأوى الطاغي المؤثِرِ للدنيا النار؛ فاحذر أنت أن يكون مأواك النارَ بالطغيانِ وإيثارِ الدنيا، واتّقِ سببهما بلزومِ حدودِ الله وإيثارِ الآخرة؛ فأمّا من طغى وآثر الحياةَ الدنيا فإنّ الجحيمَ هي المأوى؛ ومأواهم النارُ وبئس مثوى الظالمين؛ فبئس المهاد؛ فمأوى الطاغي المؤثِرِ للدنيا النار، والنجاةُ باتّقاءِ سببها؛ فاتّقِ الطغيانَ وإيثارَ الدنيا، وآثِر الآخرة؛ فمن اتّقاهما نجا، ومن جمعهما كان مأواه النار؛ فاجعل الحذرَ من أن يكون مأواك النارَ دأبك."}},{"n":40,"reflection":{"text":"«وأما من خاف مقام ربه ونهى النفس عن الهوى»، وأما من خاف قيامَه بين يدي ربّه (أو مقامَ ربّه واطّلاعَه عليه)، ونهى نفسه عن هواها المحرّم؛ ففي هذا بيانُ وصفي أهلِ السعادة: خوفِ المقامِ ونهيِ النفسِ عن الهوى؛ فاخف مقامَ ربّك وانهَ نفسك عن الهوى لتكون من أهلِ الجنّة، فهذان سبيلُ السعادة، فالزمهما.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"خوفُ مقامِ الله ونهيُ النفسِ عن الهوى."},"action":{"text":"تأمّل وصفَي أهلِ السعادة: وأما من خاف مقامَ ربّه، أي خاف قيامَه بين يدي ربّه للحسابِ يومَ القيامة، أو خاف مقامَ ربّه واطّلاعَه عليه ومراقبتَه له، فامتنع عن المعاصي، ونهى النفسَ عن الهوى، أي منع نفسه وكفّها عن هواها المحرّمِ وشهواتها الممنوعة، فخالف هواه وأطاع مولاه؛ فجمع بين خوفِ الله ومجاهدةِ النفس «وأما من خاف مقام ربه ونهى النفس عن الهوى»؛ ففي هذا بيانُ وصفي أهلِ السعادةِ الذين مأواهم الجنّة: خوفِ مقامِ الله (الذي يحمل على تركِ المعاصي)، ونهيِ النفسِ عن الهوى (الذي هو مجاهدةُ النفسِ ومخالفةُ الهوى)؛ فخوفُ الله ونهيُ النفسِ عن الهوى سبيلُ السعادة؛ فاخف أنت مقامَ ربّك واطّلاعَه عليك وقيامَك بين يديه، وانهَ نفسك عن هواها المحرّم، وخالف هواك، فإنّ ذلك سبيلُ الجنّة؛ ولمن خاف مقامَ ربّه جنّتان؛ وأمّا من خاف مقامَ ربّه ونهى النفسَ عن الهوى فإنّ الجنّةَ هي المأوى؛ ولا تتّبعِ الهوى فيضلّك عن سبيلِ الله؛ فخوفُ الله ونهيُ النفسِ عن الهوى سبيلُ السعادةِ والجنّة؛ فالزمهما، واخف الله، وخالف هواك؛ فمن خاف الله ونهى نفسه سعد، ومن أمِن واتّبع هواه شقي؛ فاجعل خوفَ مقامِ الله ونهيَ النفسِ عن الهوى دأبك."}},{"n":41,"reflection":{"text":"«فإن الجنة هي المأوى»: فإنّ الجنّةَ هي مأواه ومسكنه (جزاءَ خوفِه ونهيِه نفسه)؛ ففي هذا بيانُ أنّ مأوى من خاف ربّه ونهى نفسه الجنّة؛ فاطلب أن يكون مأواك الجنّةَ بخوفِ الله ومجاهدةِ النفس، فمأوى هذين الجنّة، فاطلبه بهما.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الجنّةِ بخوفِ الله ومجاهدةِ النفس."},"action":{"text":"تأمّل مأوى السعداء: فإنّ الجنّة، دارَ النعيم، هي المأوى، أي هي مأواه ومسكنه ومقرّه الذي يأوي إليه، جزاءَ خوفِه مقامَ ربّه ونهيِه نفسه عن الهوى؛ فمن جمع خوفَ الله ومجاهدةَ النفسِ كان مأواه الجنّة «فإن الجنة هي المأوى»؛ ففي هذا بيانُ أنّ مأوى من خاف مقامَ ربّه ونهى النفسَ عن الهوى هو الجنّة، فهي مسكنه ومقرّه، جزاءَ وصفيه؛ فمأوى الخائفِ لله المجاهدِ لنفسه الجنّة؛ فاطلب أنت أن يكون مأواك الجنّةَ بخوفِ الله ومجاهدةِ النفسِ عن الهوى، والزم هذين السببين؛ وأمّا من خاف مقامَ ربّه ونهى النفسَ عن الهوى فإنّ الجنّةَ هي المأوى؛ جناتُ عدنٍ يدخلونها؛ وأزلفتِ الجنّةُ للمتّقين؛ فمأوى الخائفِ المجاهدِ الجنّة، وتُطلَب بخوفِ الله ومجاهدةِ النفس؛ فاطلبها بهما، واخف الله، وجاهد نفسك؛ فمن خاف الله وجاهد نفسه كان مأواه الجنّة، ومن طغى شقي؛ فاجعل طلبَ الجنّةِ بخوفِ الله ومجاهدةِ النفسِ دأبك."}},{"n":42,"reflection":{"text":"«يسألونك عن الساعة أيان مرساها»: يسألك المكذّبون عن الساعةِ: متى وقتُ قيامها واستقرارها؟ (استبعادًا)؛ ففي هذا بيانُ سؤالِ المكذّبين عن وقتِ الساعةِ تعنّتًا؛ فلا تسأل عن وقتِ الساعةِ متعنّتًا، بل استعدّ لها، فالواجبُ الاستعدادُ لا السؤال، فاستعدّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للساعةِ لا السؤالُ عن وقتها تعنّتًا."},"action":{"text":"تأمّل سؤالهم: يسألونك، يا محمد، أي المكذّبون المستبعدون، عن الساعةِ، أي عن القيامة، أيّان مرساها، أي متى وقتُ قيامها ووقوعها واستقرارها؟ سؤالَ استبعادٍ وتكذيبٍ لا استرشاد «يسألونك عن الساعة أيان مرساها»؛ ففي هذا بيانُ سؤالِ المكذّبين عن وقتِ الساعةِ على وجهِ الاستبعادِ والتعنّت، لا على وجهِ الاسترشادِ والاستعداد؛ فالسؤالُ عن وقتِ الساعةِ تعنّتًا من علاماتِ التكذيب؛ فلا تسأل أنت عن وقتِ الساعةِ متعنّتًا مستبعدًا، فإنّ علمها عند الله وحده، بل استعدّ لها في كلِّ حين، فما ينفعك معرفةُ وقتها بل الاستعداد؛ يسألونك عن الساعةِ أيّان مرساها قل إنما علمها عند ربّي؛ إنّ الله عنده علمُ الساعة؛ إنّ الساعةَ آتيةٌ أكاد أخفيها؛ فالواجبُ الاستعدادُ للساعةِ لا السؤالُ عن وقتها؛ فاستعدّ لها، ولا تسأل متعنّتًا؛ فمن استعدّ للساعةِ نجا، ومن شُغِل بوقتها متعنّتًا خسر؛ فاجعل الاستعدادَ للساعةِ دأبك."}},{"n":43,"reflection":{"text":"«فيم أنت من ذكراها»: في أيِّ شيءٍ أنت من ذكرِها حتى تُسأل عنها؟ (لست ممّن يعلم وقتها فتُذكِّرهم به)؛ ففي هذا بيانُ أنّ علمَ وقتِ الساعةِ ليس إلى النبيّ؛ فكِل علمَ الغيبِ إلى الله ولا تتكلّف علمَ ما استأثر به، فوقتُ الساعةِ غيب، ففوّضه إلى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ علمِ الغيبِ إلى الله وعدمُ تكلّفِ ما استأثر به."},"action":{"text":"تأمّل نفيَ علمِ الوقت: فيم أنت، يا محمد، من ذكراها، أي في أيِّ شيءٍ أنت من ذكرِ وقتِ الساعةِ وبيانِه لهم؟ أي لست في شيءٍ من علمِ وقتها حتى تُذكِّرهم به أو تُخبِرهم عنه، فعلمها ليس إليك، بل هو ممّا استأثر الله بعلمه «فيم أنت من ذكراها»؛ ففي هذا بيانُ أنّ علمَ وقتِ الساعةِ ليس إلى النبيِّ ﷺ ولا إلى أحدٍ من الخلق، بل هو ممّا استأثر الله بعلمه، فلا يُسأل عنه النبيُّ لأنه لا يعلمه؛ فوقتُ الساعةِ غيبٌ استأثر الله بعلمه؛ فكِل أنت علمَ الغيبِ (كوقتِ الساعة) إلى الله، ولا تتكلّف علمَ ما استأثر الله بعلمه، ولا تسأل عنه، بل استعدّ؛ يسألونك عن الساعةِ أيّان مرساها قل إنما علمها عند ربّي لا يجلّيها لوقتها إلا هو؛ قل لا يعلم من في السماواتِ والأرضِ الغيبَ إلا الله؛ فعلمُ الساعةِ غيبٌ لله وحده؛ ففوّضه إليه، ولا تتكلّفه، واستعدّ؛ فمن فوّض علمَ الغيبِ لله سلم، ومن تكلّفه ضلّ؛ فاجعل تفويضَ علمِ الغيبِ إلى الله دأبك."}},{"n":44,"reflection":{"text":"«إلى ربك منتهاها»: إلى ربّك وحده منتهى علمِ الساعةِ وأمرِها؛ ففي هذا بيانُ انفرادِ الله بعلمِ الساعةِ ومنتهاها؛ فأفرِد الله بعلمِ الساعةِ ولا تصدّق مدّعيَ علمها، فمنتهى علمها إلى الله، فأفرِده به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بعلمِ الساعةِ والحذرُ من مدّعي علمها."},"action":{"text":"تأمّل انفرادَ الله بعلمها: إلى ربّك، يا محمد، منتهاها، أي إلى ربّك وحده منتهى علمِ الساعةِ وأمرِها ووقتِها، فعلمها ينتهي إليه ولا يتجاوزه إلى غيره، فهو المنفردُ بعلمِ وقتها «إلى ربك منتهاها»؛ ففي هذا بيانُ انفرادِ الله بعلمِ الساعةِ ومنتهى أمرها، فلا يعلم وقتها إلا هو، لا مَلَكٌ مقرّبٌ ولا نبيٌّ مرسل؛ فعلمُ الساعةِ ينتهي إلى الله وحده؛ فأفرِد أنت الله بعلمِ الساعة، واعتقد أنه لا يعلم وقتها سواه، ولا تصدّق من ادّعى علمها من كاهنٍ أو منجّمٍ أو غيرِهما، فمن ادّعى علمها كذب؛ إنّ الله عنده علمُ الساعة؛ يسألونك عن الساعةِ أيّان مرساها؛ وعنده مفاتحُ الغيبِ لا يعلمها إلا هو؛ فعلمُ الساعةِ لله وحده، ومدّعيه كاذب؛ فأفرِده به، وكذّب مدّعيه، واستعدّ؛ فمن أفرد الله بعلمها وحّده، ومن صدّق مدّعيه ضلّ؛ فاجعل إفرادَ الله بعلمِ الساعةِ دأبك."}},{"n":45,"reflection":{"text":"«إنما أنت منذر من يخشاها»: إنما وظيفتك، يا محمد، إنذارُ من يخشى الساعةَ (فهو المنتفعُ بالإنذار)؛ ففي هذا بيانُ أنّ وظيفةَ النبيِّ الإنذارُ، وأنّ المنتفعَ به أهلُ الخشية؛ فاخش الساعةَ لتنتفع بالإنذار، وانتفع بإنذارِ الرسول، فالخشيةُ تفتح بابَ الانتفاع، فاخش واتّعظ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخشيةُ من الساعةِ والانتفاعُ بالإنذار."},"action":{"text":"تأمّل وظيفةَ الإنذار: إنما أنت، يا محمد، منذرُ، أي إنما وظيفتك الإنذارُ والتحذير، لا الإخبارُ بوقتِ الساعة، من يخشاها، أي إنذارُ من يخشى الساعةَ ويخاف أهوالها، فهو المنتفعُ بإنذارك، بخلافِ المكذّبِ المستبعد «إنما أنت منذر من يخشاها»؛ ففي هذا بيانُ أنّ وظيفةَ النبيِّ ﷺ الإنذارُ والتحذيرُ من الساعة، لا الإخبارُ بوقتها، وأنّ المنتفعَ بالإنذارِ هو من يخشى الله ويخاف الساعة؛ فالإنذارُ وظيفةُ الرسول، والمنتفعُ به أهلُ الخشية؛ فاخش أنت الساعةَ وأهوالها لتنتفع بإنذارِ الرسول، واتّعظ بالإنذار، فإنّ من خشي الساعةَ انتفع؛ فذكّر بالقرآنِ من يخاف وعيد؛ إنما تنذر من اتّبع الذكرَ وخشي الرحمنَ بالغيب؛ لتنذر قومًا ما أُنذِر آباؤهم؛ فالإنذارُ ينفع من يخشى، والخشيةُ سبيلُ الانتفاع؛ فاخش الساعة، وانتفع بالإنذار، واتّعظ؛ فمن خشي الساعةَ انتفع بالإنذار، ومن أمِنها لم ينفعه؛ فاجعل الخشيةَ من الساعةِ والانتفاعَ بالإنذارِ دأبك."}},{"n":46,"reflection":{"text":"«كأنهم يوم يرونها لم يلبثوا إلا عشية أو ضحاها»: كأنّ المكذّبين يومَ يرون الساعةَ لم يلبثوا في الدنيا إلا عشيّةً أو ضحاها (وقتًا قصيرًا)؛ ففي هذا بيانُ قصرِ الدنيا في عينِ من يرى الآخرة؛ فلا تغترّ بطولِ الدنيا فإنها قصيرةٌ في عينِ الآخرة، فالدنيا قصيرةٌ فاعمل للباقية، فاعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استقصارُ الدنيا والعملُ للباقية."},"action":{"text":"تأمّل خاتمةَ السورةِ وقصرَ الدنيا: كأنهم، أي المكذّبون، يومَ يرونها، يومَ يرون الساعةَ ويعاينون أهوالها، لم يلبثوا، في الدنيا، أو في قبورهم، إلا عشيّةً أو ضحاها، أي إلا وقتًا قصيرًا جدًّا: قدرَ عشيّةِ يومٍ أو ضحوته؛ فيستقصرون مدّةَ الدنيا حين يعاينون طولَ الآخرةِ وأهوالها «كأنهم يوم يرونها لم يلبثوا إلا عشية أو ضحاها»؛ ففي هذا بيانُ أنّ المكذّبين يومَ القيامةِ يستقصرون مدّةَ لبثهم في الدنيا حتى كأنها عشيّةٌ أو ضحاها، لِما يرون من هولِ الآخرةِ وطولها؛ فالدنيا قصيرةٌ فانيةٌ في عينِ من يرى الآخرة؛ فلا تغترّ أنت بطولِ الدنيا وزخرفها، فإنها قصيرةٌ فانيةٌ في جنبِ الآخرة، فاعمل للباقيةِ ولا تركن إلى الفانية؛ قال كم لبثتم في الأرضِ عددَ سنين قالوا لبثنا يومًا أو بعضَ يومٍ؛ ويومَ تقوم الساعةُ يُقسِم المجرمون ما لبثوا غيرَ ساعة؛ كأن لم يلبثوا إلا ساعةً من نهار؛ فالدنيا قصيرةٌ فانية، والعاقلُ من عمل للباقية؛ فاستقصر الدنيا، واعمل للآخرة، ولا تغترّ؛ فمن عمل للباقيةِ ربح، ومن اغترّ بالفانيةِ خسر؛ فاجعل استقصارَ الدنيا والعملَ للباقيةِ دأبك."}}]}],"coverage":{"covered":46,"total":46}};
